import Foundation
import SwiftUI

// MARK: - AppLanguage（界面语言管理器）

@MainActor
final class AppLanguage: ObservableObject {
    static let shared = AppLanguage()
    static let changedNotification = Notification.Name("AppLanguageChanged")

    enum Language: String, CaseIterable {
        case zh = "zh"
        case en = "en"
        var displayName: String { switch self { case .zh: "中文"; case .en: "English" } }
        var localeIdentifier: String { switch self { case .zh: "zh_CN"; case .en: "en_US" } }
        var locale: Locale { Locale(identifier: localeIdentifier) }
    }

    @Published var current: Language {
        didSet {
            UserDefaults.standard.set(current.rawValue, forKey: "appLanguage")
            NotificationCenter.default.post(name: Self.changedNotification, object: nil)
        }
    }

    private init() {
        let raw = UserDefaults.standard.string(forKey: "appLanguage") ?? Language.zh.rawValue
        self.current = Language(rawValue: raw) ?? .zh
    }
    static var lang: Language { shared.current }

    /// 非 MainActor 安全的语言读取（直接从 UserDefaults 读取）。
    /// 供 `RelativeDateTimeFormatter`、`RankName` 等非隔离上下文使用。
    nonisolated static var currentLang: Language {
        let raw = UserDefaults.standard.string(forKey: "appLanguage") ?? Language.zh.rawValue
        return Language(rawValue: raw) ?? .zh
    }

    /// 非 MainActor 安全的 Locale 读取。
    nonisolated static var currentLocale: Locale { currentLang.locale }
}

